import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import api from "../services/api";
import { API_ENDPOINTS } from "../services/apiEndpoints";
import Footer from "../components/footer.js";

const Tweets = () => {
    const { wallId } = useParams();
    const navigate = useNavigate();
    const [tweets, setTweets] = useState([]);
    const [wall, setWall] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const logoUrl = "/path-to-logo.png"; // Fallback logo if wall.logo is unavailable

    useEffect(() => {
        const fetchWalls = async () => {
            try {
                let response = await api.get(API_ENDPOINTS.GET_TWEETS_BY_WALL(wallId));
                const tweetData = Array.isArray(response.data) ? response.data : [];
                setTweets(tweetData);
                response = await api.get(API_ENDPOINTS.GET_WALL_BY_ID(wallId));
                setWall(response.data);
                setLoading(false);
            } catch (err) {
                setError("Failed to load wall");
                setLoading(false);
            }
        };
        fetchWalls();
    }, [wallId]);

    if (loading) return <div className="text-center text-gray-600">Loading...</div>;
    if (error) return <div className="text-center text-red-600">{error}</div>;
    if (!wall) return <div className="text-center text-gray-600">Wall not found</div>;

    const handleRemoveTweet = async (index) => {
        try {
            const tweetToRemove = tweets[index];
            if (tweetToRemove && tweetToRemove.id) {
                await api.delete(API_ENDPOINTS.DELETE_TWEET(wallId, tweetToRemove.id));
            }
            setTweets(tweets.filter((_, i) => i !== index));
        } catch (err) {
            setError("Failed to remove tweet");
            console.error("Error removing tweet:", err);
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 text-gray-800 font-sans">
            {/* Header */}
            <header className="bg-white shadow-md p-6 mb-8">
                <div className="flex justify-between items-center max-w-7xl mx-auto">
                    <div className="flex items-center">
                        <img
                            src={wall?.logo || logoUrl}
                            alt="Wall Logo"
                            className="w-12 h-12 rounded-full mr-4"
                        />
                        <h1 className="text-3xl font-bold text-gray-900">{wall?.title || "Community Wall"}</h1>
                    </div>
                    <div className="space-x-4">
                        <button
                            onClick={() => navigate(`/walls/${wallId}/create-tweet`)}
                            className="bg-green-500 text-white px-6 py-2 rounded-lg hover:bg-green-600 transition duration-300"
                        >
                            Create Tweet
                        </button>
                        <button
                            onClick={() => navigate(`/walls/${wallId}/edit`)}
                            className="bg-blue-500 text-white px-6 py-2 rounded-lg hover:bg-blue-600 transition duration-300"
                        >
                            Settings
                        </button>
                    </div>
                </div>
            </header>

            {/* Tweet Section */}
            <main className="max-w-7xl mx-auto px-6 py-8">
                {tweets.length > 0 ? (
                    <div className="grid gap-6">
                        {tweets.map((tweet, index) => (
                            <div
                                key={String(tweet.id) || String(index)}
                                className="bg-white p-6 rounded-lg shadow-md hover:shadow-lg transition-shadow"
                            >
                                <div className="flex items-start">
                                    <img
                                        src={tweet.user?.avatar || "https://via.placeholder.com/40"}
                                        alt="User Avatar"
                                        className="w-10 h-10 rounded-full mr-4"
                                    />
                                    <div className="flex-1">
                                        <p className="text-lg font-medium text-gray-900">
                                            {tweet.user?.name || "Anonymous User"}
                                        </p>
                                        <p className="text-gray-600 mt-2">
                                            {tweet.text || "No tweet text"}
                                        </p>
                                    </div>
                                </div>
                                <button
                                    type="button"
                                    onClick={() => handleRemoveTweet(index)}
                                    className="mt-4 bg-red-500 text-white px-4 py-2 rounded-lg hover:bg-red-600 transition duration-300"
                                >
                                    Remove
                                </button>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="text-center text-gray-500 py-12">
                        No tweets are added yet.
                    </div>
                )}
            </main>

            {/* Footer */}
            <Footer socialLinks={wall?.socialLinks} />
        </div>
    );
};

export default Tweets;
